static void lt_input_prompt(lt_str prompt) {
    size_t n = lt_str_byte_len(prompt);
    if (n > 0u) {
        (void)fwrite(lt_str_data(&prompt), 1u, n, stdout);
        fflush(stdout);
    }
}
static lt_str lt_input_all(lt_str prompt, lt_str at) {
    (void)at;
    lt_input_prompt(prompt);
    size_t cap = 128u, len = 0u;
    char *buf = malloc(cap);
    if (buf == NULL) {
        fprintf(stderr, "MemoryFault: cannot allocate input buffer\n");
        exit(1);
    }
    int32_t cp = 0;
    int ch = fgetc(stdin);
    while (ch != EOF) {
        if (len + 1u >= cap) {
            cap *= 2u;
            buf = realloc(buf, cap);
            if (buf == NULL) {
                fprintf(stderr, "MemoryFault: cannot grow input buffer\n");
                exit(1);
            }
        }
        if (((unsigned char)ch & 0xC0u) != 0x80u) { cp += 1; }
        buf[len++] = (char)ch;
        ch = fgetc(stdin);
    }
    buf[len] = '\0';
    return lt_text_from_buf(buf, len, cp);
}

