static bool lt_cp_in_ranges(const uint32_t ranges[][2], size_t count, uint32_t cp) {
    size_t lo = 0u, hi = count;
    while (lo < hi) {
        size_t mid = lo + ((hi - lo) >> 1);
        if (cp < ranges[mid][0]) { hi = mid; }
        else if (cp > ranges[mid][1]) { lo = mid + 1u; }
        else {
            return true;
        }
    }
    return false;
}
